#!/bin/bash
# Check that the hand-written folzio-* skills are kept in sync across agents.
#
#   scripts/dev/check-skill-sync.sh
#
# Each folzio-* skill must exist in both .agents/skills and .claude/skills, with a `name` equal to
# its directory name and the same `description`. The speckit-* skills are generated by Spec Kit and
# are not checked.
set -euo pipefail

cd "$(dirname "$0")/../.."

field() {
    awk -v key="$2" '
        /^---$/ { if (++fences == 2) exit; next }
        fences == 1 && index($0, key ": ") == 1 { print substr($0, length(key) + 3) }
    ' "$1"
}

status=0

report() {
    echo "$1" >&2
    status=1
}

while IFS= read -r skill; do
    agents=".agents/skills/$skill/SKILL.md"
    claude=".claude/skills/$skill/SKILL.md"
    missing=0
    for file in "$agents" "$claude"; do
        if [[ ! -f "$file" ]]; then
            report "$file not found"
            missing=1
        elif [[ "$(field "$file" name)" != "$skill" ]]; then
            report "$file: name does not match the directory name"
        fi
    done
    if ((missing == 0)) && [[ "$(field "$agents" description)" != "$(field "$claude" description)" ]]; then
        report "$skill: description differs between $agents and $claude"
    fi
done < <(find .agents/skills .claude/skills -mindepth 1 -maxdepth 1 -name 'folzio-*' -exec basename {} \; | sort -u)

if ((status != 0)); then
    exit 1
fi

echo "folzio-* skills are in sync"
